-- Fakt kartochkalari orqa tomonining ruscha matni — 57-partiya:
-- Abdulxoliq G'ijduvoniy, Abdulla Qahhor, Abdullaxon II.
-- Bu kartochkalar qisqa va manba havolasi bilan tugaydi — havola saqlanadi.

UPDATE fact_cards SET detail_ru = 'Абдулхалик Гиждувани родился в 1103 году в Гиждуванском районе Бухарской области. Позже он вырос в наставника духовной жизни, известного всему мусульманскому Востоку. Источник: Ziyouz.com, статья «Абдулхалик Гиждувани (1103–1179)».' WHERE id = 2085;
UPDATE fact_cards SET detail_ru = 'По источнику, он знал Коран наизусть уже в девять лет. Начальное образование он получил в Гиждуване, продолжил учение в известных медресе Бухары и изучил науку толкования Корана у видного учёного своего времени по имени имам Садриддин. Источник: Ziyouz.com, статья «Абдулхалик Гиждувани (1103–1179)».' WHERE id = 2086;
UPDATE fact_cards SET detail_ru = 'В двадцать два года он встретился в Бухаре с прославленным шейхом того времени Ходжой Юсуфом Хамадани и стал его учеником. По традиции, Ходжа Хизр был его наставником в уроках, а Ходжа Юсуф стал наставником в беседе и в посвящении. Источник: Ziyouz.com, статья «Абдулхалик Гиждувани (1103–1179)».' WHERE id = 2087;
UPDATE fact_cards SET detail_ru = 'Абдулхалик Гиждувани считается основателем цепи ходжаган-накшбандия. Через путь ходжаган он привёл учение в согласие с сунной пророка Мухаммада и очистил его от разных новшеств и ложных взглядов. Источник: Ziyouz.com, статья «Абдулхалик Гиждувани (1103–1179)».' WHERE id = 2088;
UPDATE fact_cards SET detail_ru = 'Абдулхалик Гиждувани разработал восемь правил-рашха этого пути: «Хуш дар дам», «Назар бар кадам», «Сафар дар ватан», «Хилват дар анджуман», «Ёдкард», «Бозгашт», «Нигохдошт» и «Ёддошт». Источник: Ziyouz.com, статья «Абдулхалик Гиждувани (1103–1179)».' WHERE id = 2089;
UPDATE fact_cards SET detail_ru = 'Его перу принадлежат трактаты «Одоби тарикат», «Рисолаи сохибия», «Аз гуфтори Ходжа Абдулхалик Гиждувани» и «Рисолаи шайх уш-шуюх хазрати Юсуф Хамадони». Он известен и как создатель прекрасных суфийских рубаи — в статье приведены пятнадцать его рубаи в переводе Эргаша Очилова. Источник: Ziyouz.com, статья «Абдулхалик Гиждувани (1103–1179)».' WHERE id = 2090;
UPDATE fact_cards SET detail_ru = 'Абдулхалик Гиждувани умер в 1179 году. После его смерти путь ходжаган продолжили Ходжа Ориф Ревгари, а несколькими поколениями позже — такие прославленные шейхи, как Ходжа Бахауддин Накшбанд; учение широко разошлось по Туркестану, Ирану, Афганистану, Индии, Турции, Ираку и даже Северной Африке. Источник: Ziyouz.com, статья «Абдулхалик Гиждувани (1103–1179)».' WHERE id = 2091;

UPDATE fact_cards SET detail_ru = 'Абдулла Каххар родился 17 сентября 1907 года в городе Коканде. Источник: Ziyouz.com — раздел «Узбекская проза»: Абдулла Каххар (1907–1968).' WHERE id = 1936;
UPDATE fact_cards SET detail_ru = 'Абдулла Каххар окончил в 1930 году педагогический факультет Среднеазиатского государственного университета. Источник: Ziyouz.com — раздел «Узбекская проза»: Абдулла Каххар (1907–1968).' WHERE id = 1937;
UPDATE fact_cards SET detail_ru = 'Первое сатирическое стихотворение Абдуллы Каххара «Ой куйганда» было напечатано в 1924 году в журнале «Муштум» под псевдонимом «Норин шилпик». Источник: Ziyouz.com — раздел «Узбекская проза»: Абдулла Каххар (1907–1968).' WHERE id = 1938;
UPDATE fact_cards SET detail_ru = 'Известность Абдуллы Каххара как рассказчика началась с рассказа «Человек без головы» (1929). Первый его сборник рассказов «Мир молодеет» был издан в 1935 году. Источник: Ziyouz.com — раздел «Узбекская проза»: Абдулла Каххар (1907–1968).' WHERE id = 1939;
UPDATE fact_cards SET detail_ru = '«Мираж» — роман Абдуллы Каххара, написанный в 1935 году. Другое крупное сочинение писателя — роман «Огни Кошчинара» — создано в 1951 году. Источник: Ziyouz.com — раздел «Узбекская проза»: Абдулла Каххар (1907–1968).' WHERE id = 1940;
UPDATE fact_cards SET detail_ru = 'Перу Абдуллы Каххара принадлежат повести «Синичка» (1958), «Сказки о былом» (1965) и «Любовь» (1968). Эти сочинения внесли важный вклад в развитие узбекской прозы. Источник: Ziyouz.com — раздел «Узбекская проза»: Абдулла Каххар (1907–1968).' WHERE id = 1941;
UPDATE fact_cards SET detail_ru = 'Абдулла Каххар работал и в драматургии: ему принадлежат комедии «Шёлковое сюзане» (1949–1953), «Больные зубы» (1954), «Голос из гроба» (1962) и «Матушки мои» (1967). Источник: Ziyouz.com — раздел «Узбекская проза»: Абдулла Каххар (1907–1968).' WHERE id = 1942;
UPDATE fact_cards SET detail_ru = 'Абдулла Каххар мастерски переложил на узбекский язык сочинения А. С. Пушкина, Л. Толстого, Н. В. Гоголя и Чехова. Источник: Ziyouz.com — раздел «Узбекская проза»: Абдулла Каххар (1907–1968).' WHERE id = 1943;
UPDATE fact_cards SET detail_ru = 'Абдулла Каххар был удостоен в 1966 году Государственной премии имени Хамзы, а в 1967-м награждён званием народного писателя Узбекистана. Писатель умер 25 мая 1968 года в Москве. Источник: Ziyouz.com — раздел «Узбекская проза»: Абдулла Каххар (1907–1968).' WHERE id = 1944;
UPDATE fact_cards SET detail_ru = 'Хотя Абдулла Каххар умер в 1968 году, заслуги его не забыты: в 2000 году он был награждён орденом «За великие заслуги». Источник: Ziyouz.com — раздел «Узбекская проза»: Абдулла Каххар (1907–1968).' WHERE id = 1945;

UPDATE fact_cards SET detail_ru = 'Абдулла-хан II родился в 1534 году в селении Афарикент в Миянкале. Полная его родословная — Абдулла ибн Искандар-хан ибн Джанибек-султан ибн Ходжа Мухаммад ибн Абулхайр-хан; он принадлежит к династии Шейбанидов. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2092;
UPDATE fact_cards SET detail_ru = 'В мае 1557 года Абдулла-хан II взял Бухару и сделал её своей столицей. В его пору Бухара стала средоточием культуры и науки всей страны. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2093;
UPDATE fact_cards SET detail_ru = 'Абдулла-хан II боролся с шейбанидскими султанами, отказывавшимися подчиняться средоточию власти, и занял Балх (1574), Самарканд (1578), Ташкент, Сайрам, Туркестан и Фергану (1583). Дважды ходил он на Хорезм (1594 и 1596) и восстановил там власть средоточия. Заняв Синд (1583) и Кашмир (1586), он укрепил южные пределы державы. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2094;
UPDATE fact_cards SET detail_ru = 'В пору Абдуллы-хана II земли страны простирались от Кашгара до берегов Аральского и Каспийского морей, от Туркестана и Сайрама до восточной части Хорасана. Он вёл деятельную внешнюю политику. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2095;
UPDATE fact_cards SET detail_ru = 'Абдулла-хан II построил множество разных сооружений. В его пору в Бухаре было основано известное медресе Абдуллы-хана, а в стране развивались градостроительство, словесность и науки. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2096;
UPDATE fact_cards SET detail_ru = 'Как сказано в источнике, Абдулла-хан II вёл работу по укреплению системы государственного управления и особенно по проведению денежной реформы. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2097;
UPDATE fact_cards SET detail_ru = 'Абдулла-хан II писал стихи на узбекском и персидском языках под псевдонимом «Хан». В его пору были созданы такие сочинения, как «Абдулла-наме» Хафиза Таниша Бухари (1584–1589), «Хафт иклим» Амина Ахмада Рази (1583), «Тазкират уш-шуаро» Мутриби (1593–1595), а сочинение Хасанходжи Нисари «Музаккири ахбоб» было ему посвящено. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2098;
UPDATE fact_cards SET detail_ru = 'Абдулла-хан II умер 8 февраля 1598 года в Самарканде. Как сказано в источнике, его сын Абдулмумин сговорился с эмиром Мухаммадом Бакибием и устроил заговор против отца. Погребён он в комплексе Бахауддина близ Бухары. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2099;
